package com.yuegang.zhihui.knowledge.application;import com.fasterxml.jackson.databind.ObjectMapper;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.knowledge.api.*;import java.sql.*;import java.sql.Date;import java.time.*;import java.util.*;import javax.sql.*;import org.springframework.jdbc.core.*;import org.springframework.transaction.annotation.*;
public final class KnowledgeMetadataService{private final JdbcTemplate jdbc;private final ObjectMapper json;public KnowledgeMetadataService(DataSource d,ObjectMapper j){jdbc=new JdbcTemplate(d);json=j;}@Transactional public KnowledgeMetadataView update(long operator,String document,UpdateKnowledgeMetadataRequest c){long id=id(document);if(c.effectiveFrom()!=null&&c.expiresAt()!=null&&c.expiresAt().toLocalDate().isBefore(c.effectiveFrom()))throw new BusinessException(ErrorCode.VALIDATION_ERROR);int n=jdbc.update("UPDATE knowledge_document SET issuing_authority=?,effective_from=?,expires_at=?,region=?,classification=?,source_name=?,metadata_version=metadata_version+1 WHERE id=? AND metadata_version=?",c.issuingAuthority(),c.effectiveFrom(),c.expiresAt()==null?null:Timestamp.from(c.expiresAt().toInstant()),c.region(),c.classification(),c.sourceName(),id,c.version());if(n!=1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);jdbc.update("DELETE FROM knowledge_document_tag WHERE document_id=?",id);for(String name:c.tags()){String tag=name.strip();if(tag.isBlank())continue;long tagId=Math.abs((long)tag.hashCode())+1;jdbc.update("INSERT INTO knowledge_tag(id,name) VALUES(?,?) ON DUPLICATE KEY UPDATE id=id",tagId,tag);Long existing=jdbc.queryForObject("SELECT id FROM knowledge_tag WHERE name=?",Long.class,tag);jdbc.update("INSERT INTO knowledge_document_tag(document_id,tag_id) VALUES(?,?)",id,existing);}var row=view(id);var snapshot=Map.of("issuingAuthority",Objects.toString(c.issuingAuthority(),""),"effectiveFrom",Objects.toString(c.effectiveFrom(),""),"expiresAt",Objects.toString(c.expiresAt(),""),"region",Objects.toString(c.region(),""),"classification",c.classification(),"sourceName",Objects.toString(c.sourceName(),""),"tags",c.tags());String title=jdbc.queryForObject("SELECT title FROM knowledge_document WHERE id=?",String.class,id),sha=jdbc.queryForObject("SELECT sha256 FROM knowledge_document WHERE id=?",String.class,id);jdbc.update("INSERT INTO knowledge_document_version(id,document_id,version_no,title,metadata_json,content_sha256,created_by) VALUES(?,?,?,?,?,?,?)",next(),id,row.metadataVersion(),title,write(snapshot),sha,operator);return row;}public KnowledgeMetadataView view(long id){return jdbc.query("SELECT id,issuing_authority,effective_from,expires_at,region,classification,source_name,metadata_version FROM knowledge_document WHERE id=?",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);Date effective=r.getDate(3);Timestamp expires=r.getTimestamp(4);var tags=jdbc.queryForList("SELECT t.name FROM knowledge_tag t JOIN knowledge_document_tag dt ON dt.tag_id=t.id WHERE dt.document_id=? ORDER BY t.name",String.class,id);return new KnowledgeMetadataView(Long.toString(r.getLong(1)),r.getString(2),effective==null?null:effective.toLocalDate(),expires==null?null:expires.toInstant().atOffset(ZoneOffset.UTC),r.getString(5),r.getString(6),r.getString(7),tags,r.getLong(8));},id);}private String write(Object x){try{return json.writeValueAsString(x);}catch(Exception e){throw new IllegalStateException(e);}}private static long id(String x){try{return Long.parseLong(x);}catch(Exception e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}}
